const PATCHES=Object.freeze([{id:'sheep-west-meadow',kind:'sheep',x:-43,z:-39,phase:.2,range:2.1},{id:'sheep-north-meadow',kind:'sheep',x:43,z:45,phase:2.4,range:1.9},{id:'rabbit-west-meadow',kind:'rabbit',x:-44,z:34,phase:1.1,range:1.55},{id:'rabbit-east-meadow',kind:'rabbit',x:44,z:-40,phase:3.2,range:1.65}]);
export function faunaRoutine(seconds,phase,range,kind='sheep',hour=12){const resting=hour<5||hour>=21,pace=resting?.08:kind==='rabbit'?.42:.16,t=seconds*pace+phase,scale=resting?.13:1;return {offsetX:Math.sin(t)*range*scale,offsetZ:Math.sin(t*.73+phase)*range*.55*scale,heading:Math.atan2(Math.cos(t)*pace*range,Math.cos(t*.73+phase)*pace*range*.4),grazing:resting?.16:kind==='sheep'?.5+.5*Math.sin(t*1.65):.12+.12*Math.sin(t*2.1),hop:resting||kind!=='rabbit'?0:Math.pow(Math.max(0,Math.sin(t*2.65)),10)*.18,bodyBob:kind==='sheep'?Math.sin(t*2)*.018:0,resting,activity:resting?'Rest':kind==='sheep'?'Graze':'Forage'};}
function part(B,scene,name,mat,pos,scale){const m=B.MeshBuilder.CreateSphere(name,{diameter:1,segments:8},scene);m.material=mat;m.position.set(...pos);m.scaling.set(...scale);m.isPickable=false;return m;}
function merge(B,parts,parent,name){const m=B.Mesh.MergeMeshes(parts,true,true,undefined,false,false);if(!m)throw Error('Fauna merge failed: '+name);m.name=name;m.parent=parent;m.isPickable=false;return m;}
export function createAmbientFauna(B,scene,{heightAt=(x,z)=>0,shadows=null,patches=PATCHES}={}){const mat=(n,h)=>{const m=new B.StandardMaterial(n,scene);m.diffuseColor=B.Color3.FromHexString(h);m.specularColor=new B.Color3(.025,.025,.025);return m;},wool=mat('Sheep fleece','#e7dfca'),dark=mat('Animal face and legs','#51473d'),rabbit=mat('Rabbit russet fur','#96714d'),animals=[];
for(const p of patches){const root=new B.TransformNode(p.id,scene),body=[],head=[],legs=[];const add=(arr,n,m,pos,s)=>arr.push(part(B,scene,p.id+' '+n,m,pos,s));
if(p.kind==='sheep'){add(body,'fleece',wool,[0,.48,0],[.92,.58,.62]);for(const [x,y,z] of [[-.34,.68,0],[-.12,.79,-.12],[.15,.78,-.1],[.36,.68,.02],[0,.72,.2]])add(body,'curl',wool,[x,y,z],[.34,.31,.34]);add(head,'head',dark,[0,0,0],[.27,.29,.25]);add(head,'muzzle',dark,[.1,-.07,-.14],[.16,.13,.15]);}
else{add(body,'body',rabbit,[0,.34,0],[.48,.3,.34]);add(body,'tail',rabbit,[-.31,.4,.02],[.15,.15,.15]);add(head,'head',rabbit,[0,0,0],[.24,.24,.22]);add(head,'muzzle',rabbit,[.1,-.07,-.12],[.12,.1,.12]);add(head,'ear-left',rabbit,[-.09,.25,0],[.085,.29,.07]);add(head,'ear-right',rabbit,[.09,.25,0],[.085,.29,.07]);}
for(const [x,z] of (p.kind==='sheep'?[[-.27,-.2],[-.27,.2],[.27,-.2],[.27,.2]]:[[-.14,-.12],[-.14,.12],[.14,-.12],[.14,.12]])){const m=B.MeshBuilder.CreateCylinder(p.id+' leg',{diameter:.07,height:.25,tessellation:6},scene);m.material=dark;m.position.set(x,.13,z);legs.push(m);}
const bodyMesh=merge(B,body,root,p.id+' body'),headPivot=new B.TransformNode(p.id+' head pivot',scene);headPivot.parent=root;headPivot.position.set(.3,.6,0);const headMesh=merge(B,head,headPivot,p.id+' head'),legsMesh=merge(B,legs,root,p.id+' legs');root.position.set(p.x,heightAt(p.x,p.z),p.z);for(const m of [bodyMesh,headMesh,legsMesh])shadows?.addShadowCaster(m);animals.push({...p,root,bodyMesh,headPivot,headMesh,legsMesh,home:{x:p.x,z:p.z},activity:'Idle'});}
return {animals,dispose(){for(const a of animals)a.root.dispose(false,true);for(const m of [wool,dark,rabbit])m.dispose();}};}
